def test_diarization_does_not_invalidate_asr_vision_or_scenes(tmp_path):
    """Only speaker-dependent descendants change when diarization evidence changes."""
    first = context(tmp_path)
    first.states["05_diarization"] = {"key": "old", "status": "ok"}
    for stage in ("04_transcription", "06_scenes", "07_people_tracking"):
        first.step(stage, {}, lambda: ok({"unchanged": True}), code_files=["config.py"])
    second = context(tmp_path)
    second.states["05_diarization"] = {"key": "new", "status": "ok"}
    def forbidden():
        """Fail if a heavy stage is needlessly rerun."""
        raise AssertionError("unrelated heavy stage invalidated")
    for stage in ("04_transcription", "06_scenes", "07_people_tracking"):
        second.step(stage, {}, forbidden, code_files=["config.py"])
        assert second.stage_metrics[stage]["cache_hit"]
    affected = descendants("05_diarization")
    assert "10_active_speaker" in affected and "16_understanding" in affected
    assert "07_people_tracking" not in affected and "04_transcription" not in affected


