def test_vision_checkpoint_chain_rejects_duplicate_or_discontinuous_frames(tmp_path):
    """A checksummed but semantically discontinuous chain is not safe to resume."""
    import numpy as np
    from ldporto.vision import Tracker
    from ldporto.vision_checkpoint import VisionCheckpointStore
    from ldporto.core import digest
    ctx=context(tmp_path)
    store=VisionCheckpointStore(ctx,ctx.config['vision'])
    tracker=Tracker(ctx.config['vision'])
    store.save(0,0,1,[{'time':.5,'person_id':'P'}],[{'time':.5}],[],{},tracker,np.zeros((2,2),dtype=np.uint8),
               'S',1.1,10,{}, {'burst_until':2,'last_speaker':'A'})
    store.save(1,1,2,[{'time':1.5,'person_id':'P'}],[{'time':1.5}],[],{},tracker,np.zeros((2,2),dtype=np.uint8),
               'S',2.1,20,{}, {'burst_until':2,'last_speaker':'A'})
    assert store.load()['end']==2
    path=store.root/'chunk_000001.json'
    payload=read_json(path)
    payload['frames'].append({'time':1.5})
    payload['checksum']=digest({key:value for key,value in payload.items() if key!='checksum'})
    write_json(path,payload)
    restored=store.load()
    assert restored['end']==1 and restored['sampling_state']['burst_until']==2


