def test_corrupt_asr_chunk_recomputes_without_changing_clean_result(tmp_path,monkeypatch):
    """Exercise the real chunk loop with synthetic ASR output, not a model claim."""
    from copy import deepcopy
    from ldporto import transcription
    ctx=context(tmp_path)
    ctx.config['transcription'].update(source_selection='original',multipass=False,chunk_seconds=5,overlap_seconds=1)
    audio=tmp_path/'fake-audio.wav'
    audio.write_bytes(b'synthetic audio placeholder')
    monkeypatch.setattr(transcription,'ffmpeg_audio',lambda *args,**kwargs: None)
    raw={'words':[{'word':'Literal.','raw':' Literal.','start':0,'end':1,'confidence':.9,'segment_id':None}],
         'segments':[{'start':0,'end':1,'text':'Literal.','words':[{'word':'Literal.'}]}]}
    calls=[]
    monkeypatch.setattr(transcription.TranscriptionEngine,'recognize',lambda *args,**kwargs: (calls.append(True) or deepcopy(raw)))
    first=transcription.TranscriptionEngine(ctx).run({'mono':str(audio)}, {}, {'duration':3})['data']
    second=transcription.TranscriptionEngine(ctx).run({'mono':str(audio)}, {}, {'duration':3})['data']
    assert len(calls)==1 and first['words']==second['words']
    path=next((ctx.cache/'asr_chunks').glob('*.json'))
    path.write_text('corrupted',encoding='utf-8')
    third=transcription.TranscriptionEngine(ctx).run({'mono':str(audio)}, {}, {'duration':3})['data']
    assert len(calls)==2 and third['words']==first['words']


