def test_vision_real_decoder_interrupt_resume_matches_clean_fixture(tmp_path,monkeypatch):
    """Use real OpenCV frames and a fixture detector; prove resume, not neural accuracy."""
    import cv2
    import numpy as np
    from copy import deepcopy
    from ldporto import vision
    video=tmp_path/'synthetic decoder.mp4'
    writer=cv2.VideoWriter(str(video),cv2.VideoWriter_fourcc(*'mp4v'),10,(320,180))
    assert writer.isOpened()
    try:
        for index in range(50):
            frame=np.full((180,320,3),120,dtype=np.uint8)
            cv2.rectangle(frame,(50+index,30),(100+index,90),(200,40,80),-1)
            writer.write(frame)
    finally:
        writer.release()
    class FixtureDetector:
        """Explicit non-model detector with reproducible observations."""
        def __init__(self,cfg,notes,offline):
            """Expose backend attributes expected by checkpoint provenance."""
            self.face='fixture'
            self.yolo=self.hog=None
            self.calls=0
        def detect(self,frame):
            """Interrupt after a committed chunk, then reproduce constant boxes."""
            self.calls+=1
            if interrupt[0] and self.calls==7:
                raise KeyboardInterrupt()
            box={'x':.2,'y':.2,'width':.1,'height':.2}
            return [{'bbox':box,'face_bbox':box,'bbox_kind':'face','face_visible':True,'body_visible':False,
                     'eyes_position':None,'embedding':np.array([1.,0.]),'detection_confidence':.9}]
    monkeypatch.setattr(vision,'PersonDetectionEngine',FixtureDetector)
    interrupt=[True]
    cfg=load_config()
    cfg['vision'].update(active_speaker=False,body_detection=False,checkpoint_seconds=1,sample_fps=2,speech_sample_fps=2,max_thumbnails=0)
    ctx=Context(video,tmp_path/'resumed',cfg,'same-video',logging.getLogger('vision-resume'))
    ctx.output.mkdir()
    metadata={'duration':5,'fps':10,'width':320,'height':180}
    scenes=[{'scene_id':'S','start':0,'end':5}]
    with pytest.raises(KeyboardInterrupt):
        vision.VisionEngine().run(ctx,metadata,scenes,{'segments':[]})
    interrupt[0]=False
    resumed=vision.VisionEngine().run(ctx,metadata,scenes,{'segments':[]})['data']
    clean=Context(video,tmp_path/'clean',deepcopy(cfg),'same-video',logging.getLogger('vision-clean'))
    clean.output.mkdir()
    expected=vision.VisionEngine().run(clean,metadata,scenes,{'segments':[]})['data']
    assert resumed['frames']==expected['frames']
    assert resumed['observations']==expected['observations']
    assert len({frame['time'] for frame in resumed['frames']})==len(resumed['frames'])


# Generated by GitHub Copilot - Oct-05-2026
def test_stable_multiple_people_do_not_force_permanent_sampling_burst():
    """Stable studio composition settles without hiding motion/boundary bursts."""
    from ldporto.visual_sampling import SamplingScheduler
    cfg=load_config()['vision']
    scheduler=SamplingScheduler(cfg)
    fast,_=scheduler.frequency(0,speaking=True,speaker='A',boundary=True,motion=0,visible_count=2,mouth_count=2)
    stable,_=scheduler.frequency(4,speaking=True,speaker='A',boundary=False,motion=0,visible_count=2,mouth_count=2)
    assert stable<fast
    changed,_=scheduler.frequency(5,speaking=True,speaker='A',boundary=False,motion=.2,visible_count=2,mouth_count=2)
    assert changed==fast


